const PASS={
 evs:{t:`गद्यांश: प्रकृति के सफ़ाईकर्मी गिद्ध`,x:`गिद्ध बड़े पक्षी हैं, जो आकाश में बहुत ऊँचाई पर चक्कर लगाते हैं। उनकी आँखें इतनी तेज़ होती हैं कि वे बहुत दूर पड़े मरे हुए पशु को भी देख लेते हैं। गिद्ध प्रायः जीवित पशुओं का शिकार नहीं करते, बल्कि मरे हुए पशुओं का मांस खाते हैं। इस तरह वे सड़ते हुए शवों को जल्दी साफ़ कर देते हैं और बीमारियाँ फैलने से रोकते हैं। इसीलिए उन्हें “प्रकृति के सफ़ाईकर्मी” कहा जाता है। पिछले कुछ दशकों में भारत में गिद्धों की संख्या बहुत तेज़ी से घट गई। वैज्ञानिकों ने पता लगाया कि बीमार पशुओं को दी जाने वाली डाइक्लोफ़ेनाक नाम की एक दवा इसका कारण थी। ऐसे पशु के मरने पर जब गिद्ध उसका मांस खाते, तो दवा के असर से वे भी मर जाते। इसके बाद सरकार ने पशुओं के लिए इस दवा पर रोक लगा दी। अब हरियाणा के पिंजौर जैसे स्थानों पर गिद्धों के बच्चे पालकर उन्हें खुले आकाश में छोड़ा जा रहा है।`},
 l1:{t:`गद्यांश 1`,x:`जुलाई में कक्षा पाँच में एक नई छात्रा आई। उसका नाम अनु था और उसका परिवार केरल से आया था। अनु को हिंदी ठीक से बोलनी नहीं आती थी, इसलिए वह कक्षा में चुप-चुप रहती थी। जब वह कुछ बोलती, तो कुछ बच्चे उसके उच्चारण पर हँस पड़ते। एक दिन भोजन की छुट्टी में सुनीता ने देखा कि अनु अकेली बैठी है और उसकी आँखें भरी हुई हैं। सुनीता उसके पास जाकर बैठ गई और अपना टिफ़िन उसकी ओर बढ़ा दिया। उस दिन से दोनों साथ बैठने लगीं। सुनीता उसे हिंदी के नए शब्द सिखाती और अनु उसे मलयालम के शब्द तथा गणित के आसान तरीके बताती, क्योंकि गणित में वह बहुत तेज़ थी। तीन महीने बाद विद्यालय की गणित प्रश्नोत्तरी में दोनों की टीम प्रथम आई। मंच पर अनु ने साफ़ हिंदी में कहा, “मेरी सफलता का श्रेय मेरी सहेली सुनीता को जाता है।” यह सुनकर वे बच्चे भी ज़ोर-ज़ोर से ताली बजा रहे थे, जो कभी उस पर हँसते थे।`},
 l2:{t:`गद्यांश 2`,x:`<b>पतझड़ में पेड़ अपने पत्ते क्यों गिराते हैं?</b><br>भारत में पीपल, सागौन, पलाश और महुआ जैसे कई पेड़ हर वर्ष कुछ समय के लिए अपने लगभग सारे पत्ते गिरा देते हैं। इस समय को पतझड़ कहते हैं। हमारे देश में पतझड़ प्रायः सर्दियों के अंत में, फागुन के आसपास आता है। पेड़ अपनी पत्तियों के छोटे-छोटे छिद्रों से लगातार पानी भाप बनाकर बाहर निकालते रहते हैं। सूखे मौसम में मिट्टी में पानी कम हो जाता है, इसलिए पत्ते गिराकर पेड़ अपना पानी बचा लेते हैं। पत्ता गिरने से पहले पेड़ उसमें से उपयोगी पदार्थ वापस खींच लेता है। तब पत्ते का हरा रंग धीरे-धीरे मिट जाता है और वह पीला, नारंगी या भूरा दिखने लगता है। ज़मीन पर गिरे पत्ते सड़कर खाद बन जाते हैं, जिससे मिट्टी उपजाऊ होती है। कुछ ही सप्ताह बाद डालियों पर नई, कोमल कोंपलें फूट आती हैं और पेड़ फिर से हरा-भरा हो जाता है।`},
 l3:{t:`गद्यांश 3`,x:`सुबह के छह बजे थे। पहाड़ की ढलानों पर दूर-दूर तक चाय के बाग़ फैले हुए थे। झाड़ियाँ इतनी बराबर कटी हुई थीं कि ऊपर से देखने पर पूरी ढलान हरे रंग की सीढ़ियों जैसी लगती थी। घाटी में रुई जैसे सफ़ेद बादल तैर रहे थे और कभी-कभी कोई बादल बाग़ के ऊपर से गुज़रते हुए सबको भिगो जाता था। पत्तियों पर ओस की बूँदें मोतियों की तरह चमक रही थीं। तभी रंग-बिरंगे कपड़े पहने महिलाओं की एक टोली बाग़ में उतरी। सबकी पीठ पर बाँस की एक लंबी टोकरी बँधी थी, जिसकी रस्सी माथे पर टिकी थी। उनकी उँगलियाँ झाड़ियों पर तेज़ी से चल रही थीं। वे हर टहनी के सिरे से केवल दो पत्तियाँ और एक कली तोड़कर पीछे टोकरी में डाल देती थीं। काम करते-करते वे मिलकर एक लोकगीत गुनगुना रही थीं। दोपहर तक टोकरियाँ भर गईं और ताज़ी पत्तियों की हल्की-सी महक पूरे बाग़ में फैल गई।`},
 l4:{t:`गद्यांश 4`,x:`ईमानदारी का अर्थ है—मन, वचन और कर्म से सच्चा रहना। ईमानदार व्यक्ति वही कहता है जो सच है और वही करता है जो उचित है, चाहे उसे कोई देख रहा हो या नहीं। परीक्षा में नकल न करना, दुकानदार द्वारा भूल से अधिक लौटाए गए पैसे वापस कर देना और अपनी ग़लती बिना डरे मान लेना ईमानदारी के छोटे-छोटे उदाहरण हैं। कई लोग सोचते हैं कि थोड़ा-सा झूठ बोलकर या चालाकी करके वे जल्दी आगे बढ़ जाएँगे। ऐसा लाभ कुछ समय के लिए मिल भी जाए, तो भी उसकी नींव कच्ची होती है। एक बार झूठ पकड़ा जाए, तो लोग उस व्यक्ति पर फिर आसानी से विश्वास नहीं करते। इसके विपरीत, ईमानदार व्यक्ति पर सब भरोसा करते हैं और उसका मन भी शांत रहता है, क्योंकि उसे कुछ छिपाना नहीं पड़ता। इसीलिए कहा गया है कि ईमानदारी सबसे अच्छी नीति है। यह आदत बचपन से ही डालनी चाहिए।`}
};
